CREATE OR REPLACE FUNCTION private.enforce_company_restriction_on_job_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_restriction_status text;
begin
  -- PHASE3D_SIMPLE_COMPANY_RESTRICTION
  if tg_op='UPDATE' and (old.status='published' or new.status is distinct from 'published') then
    return new;
  end if;
  select r.restriction_status into v_restriction_status
    from public.company_restrictions r where r.company_id=new.company_id for share;
  if not found or v_restriction_status is distinct from 'active' then
    if tg_op='INSERT' then
      raise exception 'This Company cannot create Job Postings while restricted or without a restriction record.';
    else
      raise exception 'This Company cannot publish Job Postings while restricted or without a restriction record.';
    end if;
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.protect_jobmate_company_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role text;
begin
  if tg_op = 'delete' then
    if old.member_role = 'owner' then
      raise exception 'A Company Owner cannot be removed.'
        using errcode = 'P0001';
    end if;

    return old;
  end if;

  if tg_op = 'update'
     and old.member_role = 'owner'
     and (
       new.member_role is distinct from old.member_role
       or new.company_id is distinct from old.company_id
       or new.user_id is distinct from old.user_id
     ) then
    raise exception 'Company ownership cannot be transferred or changed.'
      using errcode = 'P0001';
  end if;

  if new.member_role = 'owner' then
    select role::text
    into v_role
    from public.users
    where user_id = new.user_id;

    if v_role is distinct from 'employer' then
      raise exception 'Only an Employer can become a Company Owner.'
        using errcode = 'P0001';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.record_company_logo_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_request public.company_logo_change_requests%rowtype;
begin
  if new.logo_storage_path is not distinct from old.logo_storage_path then return new; end if;
  select * into v_request from public.company_logo_change_requests r
  where r.company_id = new.company_id and r.storage_path = new.logo_storage_path
    and r.status = 'verified'
    and r.previous_storage_path is not distinct from old.logo_storage_path
    and not exists (select 1 from public.company_logo_history h where h.change_request_id = r.request_id);
  insert into public.company_logo_history(
    company_id, previous_storage_path, storage_path, source, change_request_id, changed_by, changed_at
  ) values (
    new.company_id, old.logo_storage_path, new.logo_storage_path,
    case when v_request.request_id is not null then 'approved_change' else 'other_change' end,
    v_request.request_id, coalesce(v_request.reviewed_by, auth.uid()), clock_timestamp()
  );
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.set_jobmate_company_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.set_jobmate_personal_signup_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_requested_role text;
begin
  select lower(
    coalesce(
      a.raw_user_meta_data ->> 'requested_role',
      'job_seeker'
    )
  )
  into v_requested_role
  from auth.users a
  where a.id = new.user_id;

  if v_requested_role is null
     or v_requested_role not in ('job_seeker', 'employer') then
    v_requested_role := 'job_seeker';
  end if;

  new.role := v_requested_role::public.user_role;
  return new;
end;
$function$

