CREATE OR REPLACE FUNCTION public.protect_job_posting_ownership()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.company_id is distinct from old.company_id
     or new.created_by is distinct from old.created_by then
    raise exception 'Job posting ownership cannot be changed.';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_job_posting_timestamps()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();

  if tg_op = 'INSERT' then
    if new.status = 'published' then
      new.published_at = now();
    else
      new.published_at = null;
    end if;

  elsif tg_op = 'UPDATE' then
    if old.status = 'draft'
       and new.status = 'published' then
      new.published_at = now();
    else
      new.published_at = old.published_at;
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_job_posting()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.status = 'published' then
    if nullif(btrim(new.role_overview), '') is null then
      raise exception
        'A role overview is required before publishing.';
    end if;

    if new.work_arrangement in ('on_site', 'hybrid')
       and nullif(btrim(new.location), '') is null then
      raise exception
        'A location is required for on-site or hybrid jobs.';
    end if;
  end if;

  if tg_op = 'UPDATE' then
    if old.status = 'closed'
       and new.status <> 'closed' then
      raise exception
        'Closed job postings cannot be reopened.';
    end if;
  end if;

  return new;
end;
$function$
